  t jsonb; s jsonb; grp jsonb; e jsonb;
  weeks int; wk int; so int;
  wks jsonb; sess jsonb; grps jsonb; exs jsonb; reps_val text;
begin
  for t in select jsonb_array_elements(spec) loop
    weeks := (t->>'weeks')::int;
    wks := '[]'::jsonb;
    for wk in 1..weeks loop
      sess := '[]'::jsonb;
      for s in select jsonb_array_elements(t->'sessions') loop
        grps := '[]'::jsonb; so := 0;
        for grp in select jsonb_array_elements(s->'groups') loop
          exs := '[]'::jsonb;
          for e in select jsonb_array_elements(grp) loop
            so := so + 1;
            if jsonb_typeof(e->'reps') = 'array' then reps_val := e->'reps'->>(wk-1);
            else reps_val := e->>'reps'; end if;
            exs := exs || jsonb_build_object(
              'exerciseId', km->>(e->>'ex'), 'sets', (e->'sets'->(wk-1)), 'reps', reps_val,
              'loadType','kg', 'loadValue',0, 'rpeTarget', e->'rpe',
              'tempo','', 'restSeconds', (e->>'rest')::int, 'notes','', 'sortOrder', so);
          end loop;
          grps := grps || jsonb_build_object('label', chr(64 + jsonb_array_length(grps) + 1), 'exercises', exs);
        end loop;
        sess := sess || jsonb_build_object('dayOfWeek', (s->>'day')::int, 'name', s->>'name',
          'type','strength', 'method', t->>'method', 'bodySplit','full',
          'groups', grps, 'estimatedDurationMin', (s->>'est')::int);
      end loop;
      wks := wks || jsonb_build_object('week', wk, 'sessions', sess);
    end loop;
    insert into training_plan_templates(team_id, created_by, name, plan_type, duration_weeks,
      sessions_per_week, readiness_enabled, deload_volume_pct, deload_intensity_pct,
      recovery_volume_pct, recovery_intensity_pct, structure, notes)
    values ('5a515036-0529-4e4d-97bf-469eca9b2296', '60b93b68-94fa-43a9-bdab-78b51056a7fb', t->>'name', 'strength', weeks, (t->>'spw')::int,
      true, 80, 85, 60, 70, wks, t->>'notes');
  end loop;
end $MIG$;
